package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Friend-only read access; no private prices, notes, account data or mutation controls. */
final class FriendProfileSheet {
 private final Context c;private final String friend;private final NativeSheet sheet;private final AccountRepository repo;private final LinearLayout panel;private final TextView state;private JSONObject profile;private JSONArray library=new JSONArray(),steam=new JSONArray();private int tab,generation,limit=24;private boolean libraryLoaded,steamLoaded;private String query="";
 FriendProfileSheet(Context c,JSONObject selected){this.c=c;friend=selected.optString("id");repo=new AccountRepository(c);sheet=new NativeSheet(c,selected.optString("nome","Perfil do amigo"));sheet.controls.setVisibility(android.view.View.VISIBLE);HorizontalScrollView scroll=new HorizontalScrollView(c);scroll.setHorizontalScrollBarEnabled(false);LinearLayout tabs=new LinearLayout(c);scroll.addView(tabs);sheet.controls.addView(scroll);String[] labels={"👤 Perfil","🎮 Jogos","🍿 Filmes","🕹 Steam"};for(int i=0;i<4;i++){int route=i;Button b=button(labels[i]);tabs.addView(b,new LinearLayout.LayoutParams(-2,-2));b.setOnClickListener(v->{tab=route;generation++;limit=24;query="";load();});}state=NativeSheet.text(c,"Carregando perfil…",13,0xffb7a6ff);sheet.body.addView(state);panel=new LinearLayout(c);panel.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(panel);sheet.dialog.setOnDismissListener(v->generation++);sheet.show();repo.friendProfile(friend,(rows,error)->{if(!sheet.dialog.isShowing())return;if(error!=null){state.setText(error);return;}profile=rows.optJSONObject(0);load();});}
 private void load(){if(profile==null)return;panel.removeAllViews();int ticket=generation;state.setText("Carregando…");if(tab==3){if(steamLoaded){render();return;}repo.friendSteam(friend,(rows,error)->{if(!sheet.dialog.isShowing()||ticket!=generation)return;if(error!=null){state.setText(error);return;}JSONObject result=rows.optJSONObject(0);if(!result.optBoolean("connected")){state.setText("Este amigo não possui Steam vinculada.");return;}steam=result.optJSONArray("jogos");if(steam==null)steam=new JSONArray();steamLoaded=true;render();});}else if(!libraryLoaded)repo.friendLibrary(friend,(rows,error)->{if(!sheet.dialog.isShowing()||ticket!=generation)return;if(error!=null){state.setText(error);return;}library=rows;libraryLoaded=true;render();});else render();}
 private void render(){panel.removeAllViews();state.setText("");if(tab==0){ImageView banner=new ImageView(c);banner.setScaleType(ImageView.ScaleType.CENTER_CROP);panel.addView(banner,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,140)));AccountImageLoader.load(banner,profile.optString("banner_url"));ImageView avatar=new ImageView(c);avatar.setImageResource(R.drawable.app_logo);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(AppStyle.shape(avatar,0xff322642,38));avatar.setClipToOutline(true);panel.addView(avatar,new LinearLayout.LayoutParams(NativeSheet.dp(c,76),NativeSheet.dp(c,76)));AccountImageLoader.load(avatar,profile.optString("avatar_url"));panel.addView(NativeSheet.text(c,profile.optString("nome"),24,0xfff4edff));panel.addView(NativeSheet.text(c,"@"+profile.optString("slug"),12,0xffada1bd));int status=ProfileStatus.index(profile.optString("status_personalizado"));panel.addView(NativeSheet.text(c,ProfileStatus.LABELS[status],14,ProfileStatus.COLORS[status]));if(!profile.isNull("bio"))panel.addView(NativeSheet.text(c,profile.optString("bio"),14,0xffc0b4d2));int games=0,media=0,done=0,plat=0;double hours=0;for(int i=0;i<library.length();i++){JSONObject x=library.optJSONObject(i);if("jogos".equals(x.optString("categoria"))){games++;hours+=x.optDouble("horas",0);String group=LibraryStatus.group(x.optString("status"),false);if(group.equals("Zerados")||group.equals("Platinados"))done++;if(group.equals("Platinados"))plat++;}else media++;}panel.addView(NativeSheet.text(c,"🎮 "+games+" jogos • 🍿 "+media+" títulos",16,0xffb9a1ff));panel.addView(NativeSheet.text(c,"🏁 "+done+" finalizados • 💎 "+plat+" platinas • ⏱ "+Math.round(hours)+" h",13,0xffffd48a));JSONArray featured=profile.optJSONArray("jogos_destaque");if(featured!=null&&featured.length()>0){panel.addView(NativeSheet.text(c,"🌟 Jogos em destaque",18,0xfff6df97));for(int i=0;i<library.length();i++){JSONObject x=library.optJSONObject(i);for(int j=0;j<featured.length();j++)if(featured.optString(j).equals(x.optString("nome"))||featured.optString(j).equals(x.optString("id"))){addCard(x,false);break;}}}JSONArray highlights=profile.optJSONArray("conquistas_destaque");if(highlights!=null&&highlights.length()>0){panel.addView(NativeSheet.text(c,"🏅 Conquistas em destaque",18,0xffffd48a));for(int i=0;i<Math.min(4,highlights.length());i++){int index=highlights.optInt(i,-1);if(index>=0&&index<AchievementTitles.NAMES.length)panel.addView(NativeSheet.text(c,AchievementIcons.forIndex(index)+" "+AchievementTitles.NAMES[index],14,0xffe9cf96));}}return;}
  EditText search=NativeSheet.input(c,"Buscar nesta biblioteca",160);search.setText(query);search.setSingleLine(true);panel.addView(search);LinearLayout grid=new LinearLayout(c);grid.setOrientation(LinearLayout.VERTICAL);panel.addView(grid);Button more=button("Ver mais títulos");panel.addView(more);Runnable draw=()->{grid.removeAllViews();JSONArray source=tab==3?steam:library;List<JSONObject> matches=new ArrayList<>();for(int i=0;i<source.length();i++){JSONObject x=source.optJSONObject(i);if(x==null||tab!=3&&("jogos".equals(x.optString("categoria"))!=(tab==1))||!x.optString("nome").toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;matches.add(x);}if(tab!=3)Collections.sort(matches,(a,b)->{String aa=(tab==2?a.optString("tipo")+" • ":"")+LibraryStatus.group(a.optString("status"),tab==2);String bb=(tab==2?b.optString("tipo")+" • ":"")+LibraryStatus.group(b.optString("status"),tab==2);return aa.compareTo(bb);});String previous="";for(int i=0;i<Math.min(limit,matches.size());i++){JSONObject x=matches.get(i);if(tab!=3){String group=(tab==2?x.optString("tipo")+" • ":"")+LibraryStatus.group(x.optString("status"),tab==2);if(!group.equals(previous)){grid.addView(NativeSheet.text(c,group,16,LibrarySectionStyle.color(LibraryStatus.group(x.optString("status"),tab==2))));previous=group;}}LinearLayout card=CatalogCard.create(c,x.optString("nome"),x.optString("capa"));grid.addView(card);ImageView image=(ImageView)card.getChildAt(0);AccountImageLoader.load(image,x.optString("capa"),x.optString(tab==3?"appid":"steam_appid"));grid.addView(NativeSheet.text(c,tab==3?"⏱ "+x.optString("horas","0")+" horas jogadas":x.optString("status"),12,0xffb4a4c8));if(tab!=3)card.setOnClickListener(v->TitleDetailsDialog.show(c,x,tab==2,(updated,deleted)->{}));}more.setVisibility(matches.size()>limit?android.view.View.VISIBLE:android.view.View.GONE);state.setText(matches.isEmpty()?"Nenhum título visível neste filtro.":matches.size()+" títulos • biblioteca do amigo");};more.setOnClickListener(v->{limit+=24;draw.run();});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int d){query=s.toString();limit=24;draw.run();}});draw.run();}
 private void addCard(JSONObject x,boolean media){LinearLayout card=CatalogCard.create(c,x.optString("nome"),x.optString("capa"));panel.addView(card);AccountImageLoader.load((ImageView)card.getChildAt(0),x.optString("capa"),x.optString("steam_appid"));card.setOnClickListener(v->TitleDetailsDialog.show(c,x,media,(updated,deleted)->{}));}
 private Button button(String label){Button b=new Button(c);b.setText(label);AppStyle.button(b,false);return b;}
}
